			target: {
				close: vi.fn(async () => {
					events.push("close");
				}),
			},
			process,
			logError: (message) => events.push(message),
			flush: vi.fn(async () => {
				events.push("flush");
			}),
		});

		process.emit("SIGTERM");
		await controller.getShutdownPromise();

		expect(events).toEqual([
			"Shutting down gracefully after SIGTERM",
			"close",
			"flush",
