interface HttpResult {
	statusCode?: number;
	headers: Record<string, string | string[] | undefined>;
	body: string;
}

function openStream(
	port: number,
	headers: Record<string, string>,
): Promise<{ ended: Promise<void> }> {
	return new Promise((resolve, reject) => {
		const client = request(
			{
				host: "127.0.0.1",
				port,
				path: "/mcp",
				method: "GET",
				headers: { Accept: "text/event-stream", ...headers },
			},
			(response) => {
				const ended = new Promise<void>((finish) => {
					response.once("end", finish);
					response.once("close", finish);
				});
				resolve({ ended });
			},
		);
		client.once("error", reject);
		client.end();
	});
}

function call(
	port: number,
	method: string,
	body?: unknown,
	extraHeaders: Record<string, string> = {},
): Promise<HttpResult> {
	return new Promise((resolve, reject) => {
		const payload = body === undefined ? undefined : JSON.stringify(body);
		const client = request(
			{
				host: "127.0.0.1",
				port,
				path: "/mcp",
				method,
				headers: {
					Accept: "application/json, text/event-stream",
					...(payload ? { "Content-Type": "application/json" } : {}),
					...extraHeaders,
				},
			},
			(response) => {
				const chunks: Buffer[] = [];
				response.on("data", (chunk: Buffer) => chunks.push(chunk));
				response.once("end", () =>
					resolve({
						statusCode: response.statusCode,
						headers: response.headers,
						body: Buffer.concat(chunks).toString("utf8"),
					}),
				);
			},
		);
		client.once("error", reject);
		if (payload) client.write(payload);
		client.end();
	});
}

function serverPort(handle: { server: Server }): number {
	const address = handle.server.address();
	if (!address || typeof address === "string") throw new Error("No address");
	return address.port;
}

function jsonBody(result: HttpResult): Record<string, unknown> {
	const json = result.body.startsWith("event:")
		? result.body
				.split("\n")
				.filter((line) => line.startsWith("data:"))
				.map((line) => line.slice("data:".length).trim())
				.join("\n")
		: result.body;
	if (!json) throw new Error(`empty response: ${JSON.stringify(result)}`);
	return JSON.parse(json) as Record<string, unknown>;
}

