if (changedPackages.size === 0) {
	console.log("No workspace package changes require a package changeset.");
	process.exit(0);
}

const { stdout: changesetDiff } = await execFileAsync(
	"git",
	[
		"diff",
		"--name-status",
		"--find-renames",
		`${since}...HEAD`,
		"--",
		".changeset",
	],
	{ cwd: root },
);
